window.products.push({"id":1117980,"name":"Noble Gems Kurt Adler Glass Santa on Christmas Train Ornament, 5.5-Inch","category":"homeandappliances","retail price":19.61,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Hlc7tuqVL._AC_SL1000_.jpg","description":"Noble Gems is a collection of beautiful glass ornaments celebrating different holidays, occasions and memories. This 5.5-inch glass Santa on Christmas Train ornament by Kurt Adler is a fun and festive addition to any holiday décor. Santa Claus is featured here aboard an incredibly decorated Christmas train, which is adorned with glitter and bows and filled with gifts. Soft white material lends a realistic, working look to the smoke stack.","images":["https://m.media-amazon.com/images/I/71Hlc7tuqVL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Noble Gems","source_asin":"B00C0UCS3A","category_path":"Home & Kitchen"},"sku":"BM-1117980","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00C0UCS3A","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00C0UCS3A","price_pending":true,"merchant_ready":false});
